//! Mantle's remove-recipes presets: the original's
//! `data/tconstruct/mantle/remove_recipes/*.json` (generated by
//! ConfigurationDataProvider for Mantle's RemoveRecipesCommand), four
//! predicate filters over recipe type and result item that a server
//! operator can apply to strip classes of vanilla recipes — ingot and
//! nugget furnace smelting, vanilla tool crafting, netherite smithing.
//!
//! In the original the presets are data only: nothing applies them
//! unless the command runs, so in a default game vanilla tools stay
//! craftable and ingots stay smeltable. The port therefore registers no
//! admission policy from here: an always-on deny would remove recipes
//! the original leaves in place, and PlutoLib's crafting-match veto sees
//! crafting grids only, while three of the four presets also target
//! smelting, blasting and smithing. What the port carries is the same
//! data in code form — the port's standing representation for Mantle
//! data, as the fluid transfers live as fluid_transfers' TRANSFERS
//! rather than shipped JSON — plus the pure matcher Mantle's command
//! would run, so a future command surface can apply a preset unchanged.

/// One node of a preset's result filter, in the original's Mantle item
/// predicate forms (`mantle:any`, `mantle:tag`, `mantle:set`,
/// `mantle:and`, `mantle:or`, `mantle:inverted`) plus the original's own
/// `tconstruct:castable` predicate.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ResultPredicate {
    /// `mantle:any`: every item matches.
    Any,
    /// `mantle:tag`: the item is a member of the named tag.
    Tag(&'static str),
    /// `mantle:set`: the item is one of the named items.
    Set(&'static [&'static str]),
    /// `mantle:and`: every sub-predicate matches.
    And(&'static [ResultPredicate]),
    /// `mantle:or`: at least one sub-predicate matches.
    Or(&'static [ResultPredicate]),
    /// `mantle:inverted`: the wrapped predicate does not match.
    Inverted(&'static ResultPredicate),
    /// `tconstruct:castable`: the item is produced by casting (the
    /// original's TinkerPredicate.CASTABLE).
    Castable,
}

impl ResultPredicate {
    /// Whether a result item satisfies the predicate. Tag membership and
    /// castability are the caller's facts (the host's tag index and the
    /// casting tables at match time), mirroring how Mantle evaluates its
    /// item predicates against a stack.
    pub fn matches(
        &self,
        item: &str,
        in_tag: &dyn Fn(&str, &str) -> bool,
        castable: &dyn Fn(&str) -> bool,
    ) -> bool {
        match self {
            ResultPredicate::Any => true,
            ResultPredicate::Tag(tag) => in_tag(item, tag),
            ResultPredicate::Set(items) => items.contains(&item),
            ResultPredicate::And(parts) => {
                parts.iter().all(|part| part.matches(item, in_tag, castable))
            }
            ResultPredicate::Or(parts) => {
                parts.iter().any(|part| part.matches(item, in_tag, castable))
            }
            ResultPredicate::Inverted(part) => !part.matches(item, in_tag, castable),
            ResultPredicate::Castable => castable(item),
        }
    }
}

/// The ingot preset's exclusion set: bricks sit in the ingots tag but
/// are not the metal ingots the preset strips (the original's inverted
/// `mantle:set` inside ingot_smelting).
const INGOT_EXCLUSIONS: ResultPredicate = ResultPredicate::Set(&[
    "minecraft:brick",
    "tconstruct:seared_brick",
    "tconstruct:scorched_brick",
]);

/// The tool preset's guard: a result that is itself modifiable is never
/// removed (the original's inverted `tconstruct:modifiable` tag inside
/// vanilla_tools).
const NOT_MODIFIABLE: ResultPredicate =
    ResultPredicate::Inverted(&ResultPredicate::Tag("tconstruct:modifiable"));

/// One remove-recipes preset, in the original data's own terms. Every
/// preset's `input` filter is `mantle:any`, so only the recipe types and
/// the result filter are modelled.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct RemovePreset {
    /// The preset's file stem under `mantle/remove_recipes/`.
    pub id: &'static str,
    /// The recipe types the preset applies to (the data's `recipe_type`,
    /// a single string or a list there, one list here).
    pub recipe_types: &'static [&'static str],
    /// The result-item filter.
    pub result: ResultPredicate,
}

/// Every preset the original ships, in ConfigurationDataProvider's
/// order.
pub const REMOVE_PRESETS: &[RemovePreset] = &[
    // Makes ingots not smeltable in furnaces (recycle in the smeltery).
    RemovePreset {
        id: "ingot_smelting",
        recipe_types: &["minecraft:smelting", "minecraft:blasting"],
        result: ResultPredicate::And(&[
            ResultPredicate::Tag("forge:ingots"),
            ResultPredicate::Inverted(&INGOT_EXCLUSIONS),
            ResultPredicate::Castable,
        ]),
    },
    // Makes nuggets not smeltable in furnaces.
    RemovePreset {
        id: "nugget_smelting",
        recipe_types: &["minecraft:smelting", "minecraft:blasting"],
        result: ResultPredicate::And(&[
            ResultPredicate::Tag("forge:nuggets"),
            ResultPredicate::Castable,
        ]),
    },
    // Removes vanilla tool crafting (tools come from the tinkers'
    // stations instead).
    RemovePreset {
        id: "vanilla_tools",
        recipe_types: &["minecraft:crafting"],
        result: ResultPredicate::And(&[
            ResultPredicate::Or(&[
                ResultPredicate::Tag("minecraft:pickaxes"),
                ResultPredicate::Tag("minecraft:axes"),
                ResultPredicate::Tag("minecraft:shovels"),
                ResultPredicate::Tag("minecraft:swords"),
                ResultPredicate::Tag("minecraft:hoes"),
                ResultPredicate::Tag("forge:tools/shields"),
                ResultPredicate::Tag("forge:tools/bows"),
                ResultPredicate::Tag("forge:tools/crossbows"),
                ResultPredicate::Tag("forge:tools/fishing_rods"),
                ResultPredicate::Tag("forge:armors"),
                ResultPredicate::Set(&[
                    "minecraft:flint_and_steel",
                    "minecraft:shears",
                    "minecraft:brush",
                ]),
            ]),
            NOT_MODIFIABLE,
        ]),
    },
    // Removes netherite smithing (netherite gear comes from casting).
    RemovePreset {
        id: "netherite_smithing",
        recipe_types: &["minecraft:smithing"],
        result: ResultPredicate::Set(&[
            "minecraft:netherite_pickaxe",
            "minecraft:netherite_axe",
            "minecraft:netherite_shovel",
            "minecraft:netherite_sword",
            "minecraft:netherite_hoe",
            "minecraft:netherite_helmet",
            "minecraft:netherite_chestplate",
            "minecraft:netherite_leggings",
            "minecraft:netherite_boots",
        ]),
    },
];

/// A preset by its file stem.
pub fn preset(id: &str) -> Option<&'static RemovePreset> {
    REMOVE_PRESETS.iter().find(|preset| preset.id == id)
}

/// Whether applying the preset would remove a recipe of the given type
/// whose result is the given item — the decision Mantle's remove-recipes
/// command makes per recipe.
pub fn preset_matches(
    preset: &RemovePreset,
    recipe_type: &str,
    result_item: &str,
    in_tag: &dyn Fn(&str, &str) -> bool,
    castable: &dyn Fn(&str) -> bool,
) -> bool {
    preset.recipe_types.contains(&recipe_type)
        && preset.result.matches(result_item, in_tag, castable)
}

#[cfg(test)]
mod tests {
    use super::*;

    /// Tag membership for the tests, following the original's tags: the
    /// ingots tag carries the bricks (which is why the ingot preset
    /// excludes them by name), and the port's own pickaxe is modifiable.
    fn in_tag(item: &str, tag: &str) -> bool {
        match tag {
            "forge:ingots" => matches!(
                item,
                "minecraft:iron_ingot"
                    | "minecraft:gold_ingot"
                    | "minecraft:brick"
                    | "tconstruct:seared_brick"
                    | "tconstruct:scorched_brick"
            ),
            "forge:nuggets" => {
                matches!(item, "minecraft:gold_nugget" | "minecraft:iron_nugget")
            }
            "minecraft:pickaxes" => {
                matches!(item, "minecraft:wooden_pickaxe" | "tconstruct:pickaxe")
            }
            "tconstruct:modifiable" => item == "tconstruct:pickaxe",
            _ => false,
        }
    }

    /// Castability for the tests: the metals and the bricks all have
    /// casting recipes in the original.
    fn castable(item: &str) -> bool {
        matches!(
            item,
            "minecraft:iron_ingot"
                | "minecraft:gold_ingot"
                | "minecraft:gold_nugget"
                | "minecraft:iron_nugget"
                | "minecraft:brick"
                | "tconstruct:seared_brick"
                | "tconstruct:scorched_brick"
        )
    }

    fn applies(preset_id: &str, recipe_type: &str, result: &str) -> bool {
        preset_matches(
            preset(preset_id).expect("preset exists"),
            recipe_type,
            result,
            &in_tag,
            &castable,
        )
    }

    #[test]
    fn all_four_presets_are_listed_with_original_recipe_types() {
        let expected = [
            ("ingot_smelting", &["minecraft:smelting", "minecraft:blasting"][..]),
            ("nugget_smelting", &["minecraft:smelting", "minecraft:blasting"][..]),
            ("vanilla_tools", &["minecraft:crafting"][..]),
            ("netherite_smithing", &["minecraft:smithing"][..]),
        ];
        assert_eq!(REMOVE_PRESETS.len(), expected.len());
        for (id, recipe_types) in expected {
            let found = preset(id).expect("preset exists");
            assert_eq!(found.recipe_types, recipe_types, "preset {id}");
        }
        assert_eq!(preset("ingot_smelting_extra"), None);
    }

    #[test]
    fn preset_filters_match_the_original_data() {
        // ingot_smelting: ingots tag, minus the three bricks, castable.
        let ingot = preset("ingot_smelting").unwrap();
        let ResultPredicate::And(ingot_parts) = ingot.result else {
            panic!("ingot preset is an and filter");
        };
        assert_eq!(ingot_parts.len(), 3);
        assert_eq!(ingot_parts[0], ResultPredicate::Tag("forge:ingots"));
        assert_eq!(
            ingot_parts[1],
            ResultPredicate::Inverted(&ResultPredicate::Set(&[
                "minecraft:brick",
                "tconstruct:seared_brick",
                "tconstruct:scorched_brick",
            ]))
        );
        assert_eq!(ingot_parts[2], ResultPredicate::Castable);

        // vanilla_tools: an or of ten tags and one set, guarded by the
        // inverted modifiable tag.
        let tools = preset("vanilla_tools").unwrap();
        let ResultPredicate::And(tool_parts) = tools.result else {
            panic!("tool preset is an and filter");
        };
        assert_eq!(tool_parts.len(), 2);
        let ResultPredicate::Or(tool_kinds) = tool_parts[0] else {
            panic!("tool preset starts with an or filter");
        };
        assert_eq!(tool_kinds.len(), 11);
        assert_eq!(
            tool_kinds[10],
            ResultPredicate::Set(&[
                "minecraft:flint_and_steel",
                "minecraft:shears",
                "minecraft:brush",
            ])
        );
        assert_eq!(
            tool_parts[1],
            ResultPredicate::Inverted(&ResultPredicate::Tag("tconstruct:modifiable"))
        );

        // netherite_smithing: exactly the nine netherite gear items.
        let netherite = preset("netherite_smithing").unwrap();
        assert_eq!(
            netherite.result,
            ResultPredicate::Set(&[
                "minecraft:netherite_pickaxe",
                "minecraft:netherite_axe",
                "minecraft:netherite_shovel",
                "minecraft:netherite_sword",
                "minecraft:netherite_hoe",
                "minecraft:netherite_helmet",
                "minecraft:netherite_chestplate",
                "minecraft:netherite_leggings",
                "minecraft:netherite_boots",
            ])
        );
    }

    #[test]
    fn any_and_set_predicates_match_their_forms() {
        // Every preset's input filter is `mantle:any`: it matches all.
        assert!(ResultPredicate::Any.matches("minecraft:stone", &in_tag, &castable));
        assert!(ResultPredicate::Any.matches("tconstruct:pickaxe", &in_tag, &castable));
    }

    #[test]
    fn ingot_preset_covers_castable_ingots_in_furnace_recipes_only() {
        assert!(applies("ingot_smelting", "minecraft:smelting", "minecraft:iron_ingot"));
        assert!(applies("ingot_smelting", "minecraft:blasting", "minecraft:gold_ingot"));
        // The named bricks are in the tag and castable, but excluded.
        assert!(!applies("ingot_smelting", "minecraft:smelting", "minecraft:brick"));
        assert!(!applies(
            "ingot_smelting",
            "minecraft:smelting",
            "tconstruct:seared_brick"
        ));
        // Not a crafting-time removal, and nuggets are the other preset.
        assert!(!applies("ingot_smelting", "minecraft:crafting", "minecraft:iron_ingot"));
        assert!(!applies("ingot_smelting", "minecraft:smelting", "minecraft:gold_nugget"));
    }

    #[test]
    fn nugget_preset_covers_nuggets_not_ingots() {
        assert!(applies("nugget_smelting", "minecraft:blasting", "minecraft:gold_nugget"));
        assert!(applies("nugget_smelting", "minecraft:smelting", "minecraft:iron_nugget"));
        assert!(!applies("nugget_smelting", "minecraft:smelting", "minecraft:iron_ingot"));
    }

    #[test]
    fn tool_preset_covers_vanilla_tools_and_spares_modifiable_results() {
        assert!(applies("vanilla_tools", "minecraft:crafting", "minecraft:wooden_pickaxe"));
        assert!(applies("vanilla_tools", "minecraft:crafting", "minecraft:shears"));
        // The port's own pickaxe matches the pickaxes tag but is
        // modifiable, so the inverted guard spares it.
        assert!(!applies("vanilla_tools", "minecraft:crafting", "tconstruct:pickaxe"));
        // Crafting only: a furnace recipe for the same result stands.
        assert!(!applies("vanilla_tools", "minecraft:smelting", "minecraft:wooden_pickaxe"));
    }

    #[test]
    fn netherite_preset_covers_smithing_of_netherite_gear_only() {
        assert!(applies(
            "netherite_smithing",
            "minecraft:smithing",
            "minecraft:netherite_chestplate"
        ));
        assert!(applies(
            "netherite_smithing",
            "minecraft:smithing",
            "minecraft:netherite_pickaxe"
        ));
        assert!(!applies(
            "netherite_smithing",
            "minecraft:crafting",
            "minecraft:netherite_chestplate"
        ));
        assert!(!applies(
            "netherite_smithing",
            "minecraft:smithing",
            "minecraft:diamond_chestplate"
        ));
    }
}
